using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using System.Linq;public static class VisualMidpointProbe{public static string Run(){var lights=Object.FindObjectsByType<Light>();var fire=Object.FindObjectsByType<ParticleSystem>().Count(p=>p.name=="Living torch flame");return "fill="+lights.FirstOrDefault(l=>l.name=="Camera visibility fill")?.intensity+" fire="+fire+" volumes="+string.Join(";",Object.FindObjectsByType<Volume>().Select(v=>v.profile.TryGet<ColorAdjustments>(out var c)?c.postExposure.value.ToString():"none"));}}
